function [u, empty] = tank_update(used, mdot, dt, prop_kg)
%TANK_UPDATE  The propellant used [kg] after a step dt at flow mdot [kg/s], and whether the tank of load prop_kg is empty.
%   used: real[kg] (passed in kg)
%   mdot: real[kg/s] (passed in kg/s)
%   dt: real[s] (passed in s)
%   prop_kg: real[kg] (passed in kg)
%   returns u: real[kg] (passed in kg)
%   returns empty: bool (passed true or false)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    u = 0;
    empty = false;
    u = (used + (mdot * dt));
    empty = (u >= prop_kg);
end
